import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { gunzipSync } from "node:zlib";

const root = process.cwd();
function absolute(path) { return resolve(root, path); }
function read(path) { return readFileSync(absolute(path), "utf8"); }
function write(path, value) { mkdirSync(dirname(absolute(path)), { recursive: true }); writeFileSync(absolute(path), value); }
function replaceExact(path, before, after, expected, label) {
  const source = read(path);
  const actual = source.split(before).length - 1;
  if (actual !== expected) throw new Error(`${label}: expected ${expected} occurrence(s) in ${path}, found ${actual}`);
  write(path, source.split(before).join(after));
}

